from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .esp_niche import require_esp_social_member

router = APIRouter()


@router.get(
    "/command-center/social/connections",
    response_class=HTMLResponse,
    include_in_schema=False,
)
def social_connections_portal(request: Request):
    _member, esp_membership, profile = require_esp_social_member(request)
    definition = profile["catalog"]
    accent = escape(definition["theme"]["accent"])
    secondary = escape(definition["theme"]["secondary"])
    niche = escape(definition["title"])
    role = esp_membership.get("roles") or (
        "owner" if esp_membership.get("status") == "owner" else "member"
    )

    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='robots' content='noindex,nofollow'><meta name='theme-color' content='#05040b'><title>ESP Social Account Connections</title><style>
:root{--accent:__ACCENT__;--secondary:__SECONDARY__;--bg:#03040a;--panel:#0d0f1b;--line:#ffffff1c;--text:#fff;--muted:#b7bbce;--green:#79e3a8;--amber:#ffd36b;--red:#ff8f9d;--cyan:#5ce8ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:radial-gradient(circle at 8% 0,var(--secondary),transparent 28%),radial-gradient(circle at 92% 4%,var(--accent),transparent 23%),linear-gradient(#03040a,#070811 65%,#020309)}a{color:inherit;text-decoration:none}button,select{font:inherit}.wrap{width:min(1240px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bee;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{font-weight:950}.brand small{display:block;color:var(--accent);font-size:.64rem;text-transform:uppercase;letter-spacing:.08em}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:12px;padding:9px 12px;font-weight:850;cursor:pointer}.btn.primary{border:0;background:linear-gradient(115deg,var(--accent),var(--secondary));color:#130b18}.btn.danger{border-color:#ff8f9d55;color:#ffd8de}.btn:disabled{opacity:.45;cursor:not-allowed}.hero{padding:42px 0 20px}.eyebrow{color:var(--accent);font-size:.72rem;font-weight:950;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(2.5rem,6vw,4.7rem);letter-spacing:-.05em;line-height:.95;margin:.14em 0 .2em}.hero h1 span{background:linear-gradient(95deg,#fff,var(--accent),var(--secondary));background-clip:text;color:transparent}.lead{color:var(--muted);max-width:980px;line-height:1.62}.toolbar,.truth,.provider,.summary{border:1px solid var(--line);background:linear-gradient(145deg,#101323e8,#080a14f0);border-radius:20px;padding:14px}.toolbar{display:grid;grid-template-columns:1fr auto;gap:9px;align-items:center;margin-bottom:12px}.field{width:100%;border:1px solid var(--line);background:#070913;color:#fff;border-radius:11px;padding:10px}.truth{margin-bottom:12px;color:#dffaff;border-color:#5ce8ff38}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:12px}.metric{border:1px solid var(--line);background:#ffffff05;border-radius:15px;padding:13px}.metric b{display:block;font-size:1.45rem}.metric small,.muted{color:var(--muted)}.providers{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.provider{min-height:285px;display:flex;flex-direction:column;gap:12px}.providerhead{display:flex;gap:11px;align-items:flex-start}.icon{width:46px;height:46px;border-radius:14px;border:1px solid var(--line);display:grid;place-items:center;background:#ffffff09;font-size:1.45rem}.provider h2{margin:0;font-size:1.3rem}.status{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:.7rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em}.status.good{color:var(--green);border-color:#79e3a850}.status.warn{color:var(--amber);border-color:#ffd36b50}.status.bad{color:var(--red);border-color:#ff8f9d55}.account{border:1px solid var(--line);background:#ffffff05;border-radius:14px;padding:11px}.account strong{display:block}.small{font-size:.72rem;line-height:1.45}.provideractions{margin-top:auto;display:flex;gap:7px;flex-wrap:wrap}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:12px}.notice.show{display:block}.notice.error{color:#ffd6dc;border-color:#ff8f9d50}.empty{border:1px dashed #ffffff2a;border-radius:16px;padding:24px;text-align:center;color:var(--muted)}.footer{border-top:1px solid var(--line);padding:28px 0 40px;margin-top:32px;color:var(--muted);font-size:.84rem}@media(max-width:950px){.providers{grid-template-columns:1fr}.summary{grid-template-columns:1fr 1fr 1fr}}@media(max-width:620px){.toolbar,.summary{grid-template-columns:1fr}.actions .optional{display:none}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/command-center'>Elevate Souls Productions<small>Private Creator & Agent Hub · Social Connections</small></a><div class='actions'><a class='btn primary' href='/command-center/social'>Social Management</a><a class='btn optional' href='/command-center/social/publish-queue'>Publish Queue</a><a class='btn optional' href='/command-center/social/approvals'>Approvals</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>__NICHE__ · __ROLE__ · Secure provider authorisation</div><h1>Connect your <span>social accounts.</span></h1><p class='lead'>Authorise the official social accounts used by this ESP Social House. Access and refresh tokens stay encrypted server-side and are never written into Social House JSON or rendered into this browser page. A connection is shown as ready only when the provider application and encrypted vault are actually configured.</p></section><div id='notice' class='notice'></div><section class='toolbar'><select id='space' class='field' aria-label='Social House'></select><button class='btn' onclick='reloadAll()'>Reload Status</button></section><section class='summary' id='summary'></section><section class='truth' id='truth'>Loading secure connection state…</section><section class='providers' id='providers'><div class='empty'>Loading provider readiness…</div></section></main><footer class='footer'><div class='wrap'><strong>Elevate Souls Productions</strong> · Private ESP Creator & Agent Social Management · Powered by Aura AI Systems</div></footer><script>
const BASE='/command-center/api/social';const q=id=>document.getElementById(id);const PROVIDERS={tiktok:{label:'TikTok',icon:'🎵',detail:'Official TikTok Login Kit + Content Posting authorisation.'},instagram:{label:'Instagram',icon:'📸',detail:'Instagram Login for Professional Business or Creator accounts.'},youtube:{label:'YouTube',icon:'▶️',detail:'Google OAuth for the authorised YouTube channel and upload scope.'}};let readiness=null,house=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(m,bad=false){const n=q('notice');n.textContent=m;n.className='notice show'+(bad?' error':'');clearTimeout(window._cn);window._cn=setTimeout(()=>n.className='notice',6500)}
async function api(path,opt={}){const r=await fetch(BASE+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(_){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
function providerConnections(name){return (house?.connections||[]).filter(c=>c.platform===name&&c.state==='connected')}
function memberOauth(c){return c?.metadata?.oauth_verified===true&&c?.metadata?.oauth_provider===c?.platform}
function statusBadge(cls,text){return `<span class="status ${cls}">${esc(text)}</span>`}
function metric(label,value){return `<div class="metric"><b>${esc(value)}</b><small>${esc(label)}</small></div>`}
function renderSummary(){const all=house?.connections||[],connected=all.filter(c=>c.state==='connected').length,oauth=all.filter(c=>c.state==='connected'&&memberOauth(c)).length,configured=Object.values(readiness?.providers||{}).filter(x=>x.configured).length;q('summary').innerHTML=metric('Connected accounts',connected)+metric('Member OAuth connections',oauth)+metric('Provider apps configured',`${configured}/3`)}
function render(){renderSummary();const vault=readiness?.encrypted_vault_ready===true;q('truth').textContent=vault?'Encrypted OAuth vault is ready. Tokens remain server-side; this page receives connection metadata only.':'Encrypted OAuth vault is not configured in this deployment. New member OAuth connections are blocked until an owner configures the vault key.';q('providers').innerHTML=Object.entries(PROVIDERS).map(([name,spec])=>providerCard(name,spec,vault)).join('')}
function providerCard(name,spec,vault){const cfg=readiness?.providers?.[name]||{},connections=providerConnections(name),oauthConnections=connections.filter(memberOauth),managedConnections=connections.filter(c=>!memberOauth(c));let badge,reason;if(!vault){badge=statusBadge('bad','Vault not ready');reason='Secure encrypted credential storage must be configured before connecting an account.'}else if(!cfg.configured){badge=statusBadge('warn','Provider app not configured');reason='ESP must configure this provider application before members can authorise accounts.'}else if(connections.length){badge=statusBadge('good','Connected');reason='At least one authorised connection is available for this Social House.'}else{badge=statusBadge('warn','Authorisation required');reason='Provider application is ready; this Social House has not authorised an account yet.'}const accounts=connections.length?connections.map(c=>{const oauth=memberOauth(c),label=c.account_label||spec.label,cap=c.supports_auto_publish?'Publishing capability enabled':'Planning / capability state only';const remove=oauth?`<button class="btn danger" onclick="disconnect('${esc(name)}','${esc(c.id)}')">Disconnect</button>`:'<span class="muted small">Deployment-managed connection</span>';return `<div class="account"><strong>${esc(label)}</strong><div class="muted small">${esc(cap)}</div><div class="muted small">${oauth?'Member-authorised OAuth credential':'Owner/deployment-managed credential state'}</div><div style="margin-top:8px">${remove}</div></div>`}).join(''):'<div class="empty small">No account connected to this Social House.</div>';const canConnect=vault&&cfg.configured&&oauthConnections.length===0;const connectLabel=connections.length?'Connect member OAuth':'Connect '+spec.label;return `<article class="provider"><div class="providerhead"><div class="icon">${spec.icon}</div><div><h2>${esc(spec.label)}</h2><div class="muted small">${esc(spec.detail)}</div></div></div><div>${badge}</div><div class="muted small">${esc(reason)}</div>${accounts}<div class="provideractions"><button class="btn primary" ${canConnect?'':'disabled'} onclick="connectProvider('${esc(name)}')">${esc(connectLabel)}</button></div></article>`}
async function loadHouse(){const id=q('space').value;if(!id){house=null;render();return}try{house=await api(`/spaces/${encodeURIComponent(id)}`);render()}catch(e){notice(e.message,true)}}
async function reloadAll(){try{const [spacesData,providerData]=await Promise.all([api('/spaces'),api('/oauth/providers')]);readiness=providerData;const spaces=spacesData.spaces||[],current=q('space').value;q('space').innerHTML=spaces.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(current&&spaces.some(s=>s.id===current))q('space').value=current;q('space').onchange=loadHouse;if(spaces.length){await loadHouse()}else{house=null;q('summary').innerHTML='';q('truth').textContent='Create a Social House in Social Management before connecting social accounts.';q('providers').innerHTML='<div class="empty">No Social Houses yet.</div>'}}catch(e){notice(e.message,true)}}
function connectProvider(provider){const space=q('space').value,cfg=readiness?.providers?.[provider];if(!space)return notice('Choose a Social House first.',true);if(readiness?.encrypted_vault_ready!==true)return notice('Encrypted OAuth vault is not configured.',true);if(!cfg?.configured)return notice(`${PROVIDERS[provider]?.label||provider} provider application is not configured.`,true);window.location.assign(`${BASE}/oauth/${encodeURIComponent(provider)}/start?space_id=${encodeURIComponent(space)}`)}
async function disconnect(provider,id){const space=q('space').value;if(!space||!id)return;try{await api(`/oauth/${encodeURIComponent(provider)}/disconnect?space_id=${encodeURIComponent(space)}&connection_id=${encodeURIComponent(id)}`,{method:'POST'});await loadHouse();notice(`${PROVIDERS[provider]?.label||provider} disconnected. The member OAuth credential is no longer available to the publishing worker.`)}catch(e){notice(e.message,true)}}
reloadAll();
</script></body></html>"""
    return HTMLResponse(
        html.replace("__ACCENT__", accent)
        .replace("__SECONDARY__", secondary)
        .replace("__NICHE__", niche)
        .replace("__ROLE__", escape(str(role).title()))
    )


__all__ = ["router"]
